import { Box, Flex, Heading, IconButton } from "@chakra-ui/react";
import { useEffect, useRef, useState } from "react";
import { COPY_BUTTON_TOOLTIP, COPY_BUTTON_TOOLTIP_COPIED } from "../constants";
import { ArrowToBottom, Clone, Code, FileCheck, Icon, Refresh } from "../Icon";
import { useInspectorContext } from "../InspectorContext";
import { OnboardingTooltip } from "../OnboardingTooltip";
import { PopoverMenu } from "../PopoverMenu";
import { PopoverMenuItem } from "../PopoverMenuItem";
import { useInspectorStore } from "../store";
import { SwitchButton } from "../SwitchButton";
import { Tooltip } from "../Tooltip";
import type { Conversation } from "../types";
import { copyConversation, downloadE2eTests, downloadRawTrackerLogs } from "../utils";
import { LangfuseSessionButton } from "./LangfuseSessionButton";

const COPY_BUTTON_TOOLTIP_DELAY = 160;
const COPY_BUTTON_TOOLTIP_COPIED_TIMEOUT = 2000;

interface ChatHeaderProps {
  onNewConversation: () => void;
  flowView: boolean;
  setFlowView: (flowView: boolean) => void;
  conversationList: Conversation[];
  sessionId: string;
}

export const ChatHeader = ({
  onNewConversation,
  flowView,
  setFlowView,
  conversationList,
  sessionId,
}: ChatHeaderProps) => {
  const hasEvents = conversationList.some((c) => c.totalNumberOfUserMessages > 0);
  const { logError, showToast } = useInspectorContext();
  const isEmbedded = useInspectorStore((s) => s.isEmbedded);
  const [isCopyTooltipForcedOpen, setIsCopyTooltipForcedOpen] = useState(false);
  const [copyButtonTooltip, setCopyButtonTooltip] = useState(COPY_BUTTON_TOOLTIP);

  const copyTooltipTimeoutRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const copyTooltipContentDelayRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  useEffect(
    () => () => {
      clearTimeout(copyTooltipTimeoutRef.current);
      clearTimeout(copyTooltipContentDelayRef.current);
    },
    [],
  );

  const handleCopyConversation = async () => {
    try {
      await copyConversation(conversationList);
      clearTimeout(copyTooltipTimeoutRef.current);
      setCopyButtonTooltip(COPY_BUTTON_TOOLTIP_COPIED);
      setIsCopyTooltipForcedOpen(true);
      copyTooltipTimeoutRef.current = setTimeout(() => {
        setIsCopyTooltipForcedOpen(false);
        copyTooltipContentDelayRef.current = setTimeout(
          () => setCopyButtonTooltip(COPY_BUTTON_TOOLTIP),
          COPY_BUTTON_TOOLTIP_DELAY,
        );
      }, COPY_BUTTON_TOOLTIP_COPIED_TIMEOUT);
    } catch (error) {
      logError(error, {
        tags: {
          component: "ChatHeader",
          action: "copyConversation",
        },
      });
      showToast({
        title: "Copy failed",
        description: "Could not copy conversation to clipboard.",
        type: "error",
      });
    }
  };

  return (
    <Flex justifyContent="space-between" flex={1} alignItems="center" bg="bg.panel">
      {isEmbedded ? (
        <OnboardingTooltip target="inspectToggle">
          <SwitchButton
            item={{ value: "inspect", label: "Inspect" }}
            onActivate={() => setFlowView(!flowView)}
            isActive={flowView}
            aria-label="Toggle inspect"
            data-testid="inspect-toggle"
          />
        </OnboardingTooltip>
      ) : (
        <Heading textStyle="sm">Preview</Heading>
      )}
      <Box display="flex" gap="1" alignItems="center">
        <Tooltip
          content={copyButtonTooltip}
          showArrow
          open={isCopyTooltipForcedOpen ? true : undefined}
          contentProps={{
            _closed: { animation: "none" },
          }}
          closeDelay={0}
        >
          <IconButton
            aria-label="Copy conversation"
            data-testid="copy-conversation-button"
            variant="ghost"
            size="sm"
            disabled={!hasEvents}
            onClick={() => void handleCopyConversation()}
          >
            <Icon icon={Clone} />
          </IconButton>
        </Tooltip>
        <PopoverMenu
          trigger={
            <IconButton
              aria-label="Download"
              data-testid="download-button"
              variant="ghost"
              size="sm"
              disabled={!hasEvents}
            >
              <Icon icon={ArrowToBottom} />
            </IconButton>
          }
          tooltipContent="Download..."
        >
          <PopoverMenuItem
            icon={FileCheck}
            label="E2E tests"
            onClick={() => downloadE2eTests(conversationList, sessionId)}
            testId="download-e2e"
          />
          <PopoverMenuItem
            icon={Code}
            label="Tracker logs"
            onClick={() => downloadRawTrackerLogs(conversationList, sessionId)}
            testId="download-tracker-logs"
          />
        </PopoverMenu>
        <LangfuseSessionButton conversationList={conversationList} sessionId={sessionId} />
        <Tooltip content="Restart conversation" showArrow>
          <IconButton
            aria-label="Restart conversation"
            data-testid="restart-conversation"
            variant="ghost"
            onClick={onNewConversation}
            size="sm"
          >
            <Icon icon={Refresh} />
          </IconButton>
        </Tooltip>
      </Box>
    </Flex>
  );
};
